func:
const body = msg.payload || {};

const date = String(body.date || "").trim();
const shift = String(body.shift || "").trim();
const line = String(body.line || "").trim();
const stopStart_ts = Number(body.stopStart_ts);
const reason = String(body.reason || "").trim();
const machine = String(body.machine || "").trim();

const downtimeType =
    String(body.downtimeType || "unplanned").toLowerCase() === "planned"
        ? "planned"
        : "unplanned";

const plannedCategory =
    downtimeType === "planned"
        ? String(body.plannedCategory || "").toLowerCase()
        : null;

const downtimeCode = String(body.downtimeCode || "").trim();

if (!date || !shift || !line || !Number.isFinite(stopStart_ts)) {
    msg.statusCode = 400;
    msg.payload = {
        success: false,
        error: "Invalid downtime record identifier"
    };
    return [null, msg];
}

if (!reason) {
    msg.statusCode = 400;
    msg.payload = {
        success: false,
        error: "Downtime reason is required"
    };
    return [null, msg];
}

if (!machine) {
    msg.statusCode = 400;
    msg.payload = {
        success: false,
        error: "Please select a machine from the registered machine list"
    };
    return [null, msg];
}

if (
    downtimeType === "planned" &&
    !["standard", "additional"].includes(plannedCategory)
) {
    msg.statusCode = 400;
    msg.payload = {
        success: false,
        error: "Planned downtime category is required"
    };
    return [null, msg];
}

// Keep the original downtime information while MongoDB validates machine.
msg.downtimeUpdate = {
    date,
    shift,
    line,
    stopStart_ts,
    reason,
    machine,
    downtimeType,
    plannedCategory,
    downtimeCode
};

// Escape RegExp characters before exact case-insensitive comparison.
const escapedMachine = machine.replace(/[.*+?^${}()|[\\]\\\\]/g, "\\$&");

// Query machines master.
// Machine must:
//   1. belong to this line
//   2. exactly match machineName
//   3. be active
msg.payload = [{
    line: line,
    machineName: {
        $regex: "^" + escapedMachine + "$",
        $options: "i"
    },
    active: {
        $ne: false
    }
}];

return [msg, null];

const machineRecord = msg.payload || null;
const d = msg.downtimeUpdate || {};

if (!machineRecord || !machineRecord.machineName) {
    msg.statusCode = 400;
    msg.headers = {
        "Content-Type": "application/json"
    };

    msg.payload = {
        success: false,
        error: `Machine "${d.machine || ""}" is not registered as an active machine for ${d.line || "selected line"}. Please select a valid machine from the list.`
    };

    return [null, msg];
}

// Use the canonical machine name stored in MongoDB.
// This avoids case/spelling variations in historical downtime data.
const canonicalMachine = String(machineRecord.machineName);
const machineCode = String(machineRecord.machineCode || "");

msg.operation = "updateOne";
msg.collection = "stoppages";
msg.mode = "collection";

msg.payload = [
    {
        date: d.date,
        shift: d.shift,
        line: d.line,
        stopStart_ts: d.stopStart_ts
    },
    {
        $set: {
            reason: d.reason,
            machine: canonicalMachine,
            machineCode: machineCode,
            downtimeType: d.downtimeType,
            plannedCategory: d.plannedCategory,
            downtimeCode: d.downtimeCode,
            updatedAt: new Date().toISOString()
        }
    }
];

return [msg, null];

const d = msg.downtimeUpdate || {};
const result = msg.payload || {};

const matched = Number(
    result.matchedCount ??
    result.result?.n ??
    result.n ??
    0
);

if (matched < 1) {
    msg.statusCode = 404;
    msg.payload = {
        success: false,
        error: "Downtime record was not found"
    };
    return [null, msg];
}

// Keep HTTP request/response objects and the edited shift identity.
msg._httpReq = msg.req;
msg._httpRes = msg.res;
msg.recalcInfo = {
    date: String(d.date || ""),
    shift: String(d.shift || ""),
    line: String(d.line || "")
};

// Find the exact completed shift document.
msg.collection = "shifts";
msg.operation = "findOne";
msg.payload = [{
    "lineStats.shiftDate": msg.recalcInfo.date,
    "lineStats.shift": msg.recalcInfo.shift,
    "lineStats.lineName": msg.recalcInfo.line
}];

return [msg, null];

const shiftDoc = msg.payload || null;

if (!shiftDoc || !shiftDoc.lineStats) {

    const d = msg.downtimeUpdate || {};

    const requestedDate =
        String(d.date || "").trim();

    const requestedShift =
        String(d.shift || "").trim();


    // ========================================================
    // CALCULATE CURRENT SHIFT
    //
    // This intentionally uses the same Asia/Colombo shift-date
    // convention as the counter flow:
    //
    // 06:00-14:00 -> today's date
    // 14:00-22:00 -> today's date
    // 22:00-24:00 -> today's date
    // 00:00-06:00 -> PREVIOUS day's date, shift 22-06
    // ========================================================

    function getCurrentShiftInfo(timestamp = Date.now()) {

        const p = {};

        for (
            const x of new Intl.DateTimeFormat(
                "en-CA",
                {
                    timeZone: "Asia/Colombo",
                    year: "numeric",
                    month: "2-digit",
                    day: "2-digit",
                    hour: "2-digit",
                    hourCycle: "h23"
                }
            ).formatToParts(new Date(timestamp))
        ) {
            if (x.type !== "literal") {
                p[x.type] = x.value;
            }
        }

        const y = Number(p.year);
        const m = Number(p.month);
        const day = Number(p.day);
        const h = Number(p.hour);

        const fmt = (yy, mm, dd) =>
            `${String(yy).padStart(4, "0")}-${String(mm).padStart(2, "0")}-${String(dd).padStart(2, "0")}`;

        let shiftName;
        let shiftDate;

        if (h >= 6 && h < 14) {

            shiftName = "06-14";
            shiftDate = fmt(y, m, day);

        } else if (h >= 14 && h < 22) {

            shiftName = "14-22";
            shiftDate = fmt(y, m, day);

        } else if (h >= 22) {

            shiftName = "22-06";
            shiftDate = fmt(y, m, day);

        } else {

            shiftName = "22-06";

            const dt =
                new Date(Date.UTC(y, m - 1, day));

            dt.setUTCDate(
                dt.getUTCDate() - 1
            );

            shiftDate =
                dt.toISOString().slice(0, 10);
        }

        return {
            shiftName,
            shiftDate
        };
    }


    const current =
        getCurrentShiftInfo();


    const isCurrentShift =
        requestedDate === current.shiftDate &&
        requestedShift === current.shiftName;


    // ========================================================
    // CURRENT SHIFT
    //
    // No saved "shifts" document is expected yet.
    // The stoppage update has already succeeded.
    // Live dashboard calculations will use the changed stoppage.
    // ========================================================

    if (isCurrentShift) {

        msg.statusCode = 200;

        msg.headers = {
            "Content-Type": "application/json"
        };

        msg.req =
            msg._httpReq || msg.req;

        msg.res =
            msg._httpRes || msg.res;

        msg.payload = {
            success: true,
            downtimeUpdated: true,
            shiftSummaryUpdated: false,
            currentShift: true,

            message:
                "Downtime updated successfully. Current shift summary is calculated live.",

            line:
                String(d.line || ""),

            date:
                requestedDate,

            shift:
                requestedShift
        };

        return [null, msg];
    }


    // ========================================================
    // COMPLETED / HISTORICAL SHIFT
    //
    // A completed shift SHOULD have a saved shift summary.
    // Do not silently treat a missing document as success.
    //
    // IMPORTANT:
    // The stoppage itself has already been updated at this point,
    // therefore report the partial-success condition explicitly.
    // ========================================================

    msg.statusCode = 409;

    msg.headers = {
        "Content-Type": "application/json"
    };

    msg.req =
        msg._httpReq || msg.req;

    msg.res =
        msg._httpRes || msg.res;

    msg.payload = {
        success: false,
        downtimeUpdated: true,
        shiftSummaryUpdated: false,
        currentShift: false,

        error:
            "Downtime was updated, but the saved shift summary for this completed shift was not found.",

        line:
            String(d.line || ""),

        date:
            requestedDate,

        shift:
            requestedShift,

        currentShiftInfo: {
            date: current.shiftDate,
            shift: current.shiftName
        }
    };

    return [null, msg];
}

const s = shiftDoc.lineStats;

msg.shiftDocumentId = shiftDoc._id;
msg.previousLineStats = s;

// Rebuild exactly the input expected by the existing
// Calculate Line Shift Statistics node.
msg.summaryRequest = {
    device: String(s.device || ""),
    line: String(s.lineName || ""),
    machine: String(s.machine || ""),
    shift: String(s.shift || ""),
    shiftDate: String(s.shiftDate || ""),
    fromTime: s.shiftStart,
    toTime: s.shiftEnd,
    tileCount: Number(s.tileCount || 0),
    shiftStatus: String(s.status || "Unknown")
};

if (
    !msg.summaryRequest.device ||
    !msg.summaryRequest.shift ||
    !msg.summaryRequest.shiftDate ||
    !msg.summaryRequest.fromTime ||
    !msg.summaryRequest.toTime
) {
    msg.statusCode = 500;
    msg.req = msg._httpReq || msg.req;
    msg.res = msg._httpRes || msg.res;
    msg.payload = {
        success: false,
        error: "Saved shift summary does not contain enough information to recalculate"
    };
    return [null, msg];
}

// Re-read all stoppages AFTER the edited stoppage has been saved.
msg.collection = "stoppages";
msg.operation = "find";
msg.payload = [
    {
        device: msg.summaryRequest.device,
        date: msg.summaryRequest.shiftDate,
        shift: msg.summaryRequest.shift
    },
    {
        sort: { stopStart_ts: 1 }
    }
];

return [msg, null];

const rows = Array.isArray(msg.payload) ? [...msg.payload] : [];
const r = msg.summaryRequest;

if (!r) return null;

// ========================================================
// GET CONFIGURATION
// ========================================================

const cfgAll = global.get("counterConfig") || {};
const cfg = cfgAll[r.device] || {};

const allSettings = global.get("lineSettings") || {};

const ls =
    allSettings[r.line] ||
    allSettings[String(r.line).toLowerCase()] ||
    {};


const lineSpeed =
    Math.max(
        0,
        Number(
            ls.lineSpeed ??
            cfg.lineSpeed ??
            0
        )
    );


const tileSize =
    String(
        ls.tileSize ??
        cfg.tileSize ??
        ""
    ).trim();


const configuredPlannedDowntime =
    Math.max(
        0,
        Number(
            ls.plannedDowntime ??
            cfg.plannedDowntime ??
            0
        )
    );


// ========================================================
// SHIFT TIME RANGE
// ========================================================

const fromMs =
    new Date(r.fromTime).getTime();

const toMs =
    new Date(r.toTime).getTime();

const now =
    Date.now();


if (
    !Number.isFinite(fromMs) ||
    !Number.isFinite(toMs) ||
    toMs <= fromMs
) {
    node.error(
        "Invalid shift time range",
        msg
    );

    return null;
}


// ========================================================
// HELPERS
// ========================================================

function round(v, n = 2) {

    const p =
        10 ** n;

    return Math.round(
        (Number(v || 0) + Number.EPSILON) * p
    ) / p;
}


function tileAreaM2(size) {

    const d =
        String(size || "")
            .toLowerCase()
            .replace(/\s+/g, "")
            .split("x")
            .map(Number);

    if (
        d.length !== 2 ||
        !d.every(
            v =>
                Number.isFinite(v) &&
                v > 0
        )
    ) {
        return 0;
    }

    // Tile dimensions assumed to be centimetres.
    return (
        d[0] *
        d[1]
    ) / 10000;
}


// ========================================================
// SHIFT TIME
// ========================================================

const calculationEndMs =
    Math.min(
        Math.max(now, fromMs),
        toMs
    );


const fullShiftMinutes =
    Math.max(
        0,
        (toMs - fromMs) / 60000
    );


const elapsedMinutes =
    Math.max(
        0,
        (calculationEndMs - fromMs) / 60000
    );


// ========================================================
// CLASSIFY DOWNTIME
//
// FINAL RULE:
//
// Planned -> Standard
//     Actual recorded duration is planned,
//     but limited by configured standard allowance.
//
//     Any duration above the allowance becomes
//     UNPLANNED.
//
// Planned -> Additional
//     Entire recorded duration is planned.
//
// Everything else
//     Unplanned.
//
// IMPORTANT:
//
// Unused configured standard allowance is NOT
// automatically distributed across the shift.
// ========================================================

let totalDowntimeMinutes = 0;

let standardActualMinutes = 0;
let additionalPlannedMinutes = 0;
let explicitUnplannedMinutes = 0;

let completedStops = 0;
let openStop = false;

let currentOpenStopMinutes = 0;
let maximumDowntimeMinutes = 0;


for (const stop of rows) {

    let start =
        Number(stop.stopStart_ts);

    if (!Number.isFinite(start)) {
        continue;
    }


    // Clamp start to shift boundary.
    start =
        Math.max(
            start,
            fromMs
        );


    const isOpen =
        stop.stopStop_ts === null ||
        stop.stopStop_ts === undefined;


    let end;

    if (isOpen) {

        end =
            calculationEndMs;

    } else {

        end =
            Number(
                stop.stopStop_ts
            );

        if (!Number.isFinite(end)) {
            continue;
        }

        end =
            Math.min(
                end,
                calculationEndMs,
                toMs
            );
    }


    if (end <= start) {
        continue;
    }


    const durationMinutes =
        (end - start) / 60000;


    // ----------------------------------------
    // TOTAL ACTUAL DOWNTIME
    // ----------------------------------------

    totalDowntimeMinutes +=
        durationMinutes;


    maximumDowntimeMinutes =
        Math.max(
            maximumDowntimeMinutes,
            durationMinutes
        );


    // ----------------------------------------
    // CLASSIFICATION
    // ----------------------------------------

    const downtimeType =
        String(
            stop.downtimeType ||
            "unplanned"
        ).toLowerCase();


    const plannedCategory =
        String(
            stop.plannedCategory ||
            ""
        ).toLowerCase();


    if (
        downtimeType === "planned" &&
        plannedCategory === "standard"
    ) {

        standardActualMinutes +=
            durationMinutes;

    }

    else if (
        downtimeType === "planned" &&
        plannedCategory === "additional"
    ) {

        additionalPlannedMinutes +=
            durationMinutes;

    }

    else {

        explicitUnplannedMinutes +=
            durationMinutes;

    }


    // ----------------------------------------
    // STOP COUNTS
    // ----------------------------------------

    if (isOpen) {

        openStop = true;

        currentOpenStopMinutes =
            Math.max(
                currentOpenStopMinutes,
                durationMinutes
            );

    } else {

        completedStops += 1;

    }
}


// ========================================================
// STANDARD PLANNED DOWNTIME
// ========================================================

const allowance =
    configuredPlannedDowntime;


// IMPORTANT:
//
// If allowance = 0,
// manually classified Standard Planned downtime
// remains planned.
//
// This matches the live KPI rule.

const standardUsed =
    allowance > 0
        ? Math.min(
            standardActualMinutes,
            allowance
        )
        : standardActualMinutes;


const remainingStandardAllowance =
    allowance > 0
        ? Math.max(
            0,
            allowance -
            standardUsed
        )
        : 0;


const standardExcess =
    allowance > 0
        ? Math.max(
            0,
            standardActualMinutes -
            allowance
        )
        : 0;



const standardApplied =
    standardUsed;


// ========================================================
// PLANNED / UNPLANNED DOWNTIME
// ========================================================

const plannedDowntimeMinutes =
    standardApplied +
    additionalPlannedMinutes;


// Everything not accepted as planned is unplanned.
//
// This automatically includes:
//     explicit unplanned
//     standard excess

const unplannedDowntimeMinutes =
    Math.max(
        0,
        totalDowntimeMinutes -
        plannedDowntimeMinutes
    );


// ========================================================
// PRODUCTION TIME
// ========================================================

// Planned production time:
//
// Elapsed shift time minus accepted planned downtime.

const plannedProductionMinutes =
    Math.max(
        0,
        elapsedMinutes -
        plannedDowntimeMinutes
    );


// IMPORTANT:
//
// Physical operating time depends ONLY on
// actual stoppage duration.
//
// Planned/unplanned classification does not
// change physical operating time.

// ========================================================
// RUN CONFIRMATION CORRECTION
// ========================================================
//
// STOP_END is confirmed only after the line has been running
// continuously for requiredRunTimeMs.
//
// Tiles are already counted during this confirmation period,
// while that same period is still included in the recorded
// downtime. Add it back once for every COMPLETED stop.
//
// Open stops are intentionally excluded because they have not
// completed the recovery-confirmation period yet.

const requiredRunTimeMs =
    Math.max(
        0,
        Number(
            ls.requiredRunTimeMs ??
            cfg.requiredRunTimeMs ??
            60000
        )
    );

const runConfirmationMinutes =
    requiredRunTimeMs / 60000;

const recoveryCorrectionMinutes =
    completedStops *
    runConfirmationMinutes;

const actualOperatingMinutes =
    Math.max(
        0,
        Math.min(
            elapsedMinutes,
            elapsedMinutes -
            totalDowntimeMinutes +
            recoveryCorrectionMinutes
        )
    );


// ========================================================
// AVAILABILITY
// ========================================================

const availability =
    plannedProductionMinutes > 0
        ? (
            actualOperatingMinutes /
            plannedProductionMinutes
        ) * 100
        : 0;


// ========================================================
// PRODUCTION
// ========================================================

const tileCount =
    Math.max(
        0,
        Number(
            r.tileCount || 0
        )
    );


const areaPerTile =
    tileAreaM2(
        tileSize
    );


const production =
    tileCount *
    areaPerTile;


// ========================================================
// TARGET PRODUCTION
//
// Target is based on PHYSICAL OPERATING TIME.
//
// Example:
//
// Operating time = 400 min
// Rated speed    = 12 tiles/min
//
// Target = 4,800 tiles
// ========================================================

const targetTiles =
    lineSpeed > 0
        ? lineSpeed *
          actualOperatingMinutes
        : 0;


const targetProduction =
    targetTiles *
    areaPerTile;


// ========================================================
// PERFORMANCE
// ========================================================

const performance =
    targetTiles > 0
        ? (
            tileCount /
            targetTiles
        ) * 100
        : 0;


// ========================================================
// QUALITY
// ========================================================

// No reject / quality counter is currently available.
// Therefore quality remains 100%.

const quality =
    100;


// ========================================================
// OLE
// ========================================================

const ole =
    (
        availability *
        performance *
        quality
    ) / 10000;


// ========================================================
// BUILD SHIFT SUMMARY
// ========================================================

msg.payload = {

    lineStats: {

        // ----------------------------------------
        // IDENTIFICATION
        // ----------------------------------------

        device:
            r.device,

        lineName:
            r.line,

        machine:
            r.machine || "",

        shift:
            r.shift,

        shiftDate:
            r.shiftDate,

        shiftStart:
            r.fromTime,

        shiftEnd:
            r.toTime,

        status:
            r.shiftStatus ||
            "Unknown",


        // ----------------------------------------
        // KPI
        // ----------------------------------------

        ole:
            round(ole),

        availability:
            round(availability),

        performance:
            round(performance),

        quality:
            quality,


        // ----------------------------------------
        // PRODUCTION
        // ----------------------------------------

        tileCount:
            Math.round(tileCount),

        production:
            round(production),

        productionUnit:
            "m²",

        targetTiles:
            round(targetTiles, 0),

        targetProduction:
            round(targetProduction),


        // ----------------------------------------
        // SHIFT TIME
        // ----------------------------------------

        fullShiftMinutes:
            round(fullShiftMinutes),

        elapsedShiftMinutes:
            round(elapsedMinutes),

        plannedProductionMinutes:
            round(
                plannedProductionMinutes
            ),

        actualOperatingMinutes:
            round(
                actualOperatingMinutes
            ),


        // ----------------------------------------
        // DOWNTIME
        // ----------------------------------------

        totalDowntimeMinutes:
            round(
                totalDowntimeMinutes
            ),

        plannedDowntimeMinutes:
            round(
                plannedDowntimeMinutes
            ),

        unplannedDowntimeMinutes:
            round(
                unplannedDowntimeMinutes
            ),


        // ----------------------------------------
        // STANDARD PLANNED
        // ----------------------------------------

        configuredPlannedDowntime:
            round(
                configuredPlannedDowntime
            ),

        recordedStandardDowntimeMinutes:
            round(
                standardActualMinutes
            ),

        standardPlannedDowntimeMinutes:
            round(
                standardApplied
            ),

        remainingStandardAllowanceMinutes:
            round(
                remainingStandardAllowance
            ),

        standardExcessDowntimeMinutes:
            round(
                standardExcess
            ),


        // ----------------------------------------
        // ADDITIONAL PLANNED
        // ----------------------------------------

        additionalPlannedDowntimeMinutes:
            round(
                additionalPlannedMinutes
            ),

        appliedPlannedDowntime:
            round(
                plannedDowntimeMinutes
            ),


        // ----------------------------------------
        // STOP INFORMATION
        // ----------------------------------------

        completedStops:
            completedStops,

        totalStops:
            rows.length,

        openStop:
            openStop,

        currentOpenStopMinutes:
            round(
                currentOpenStopMinutes
            ),

        maximumDowntimeMinutes:
            round(
                maximumDowntimeMinutes
            ),


        // ----------------------------------------
        // LINE CONFIGURATION
        // ----------------------------------------

        ratedLineSpeed:
            lineSpeed,

        tileSize:
            tileSize,

        stopDelayMs:
            Number(
                ls.stopDelayMs ??
                cfg.stopDelayMs ??
                60000
            ),

        maxPulseGapMs:
            Number(
                ls.maxPulseGapMs ??
                cfg.maxPulseGapMs ??
                10000
            ),

        requiredRunTimeMs:
            Number(
                ls.requiredRunTimeMs ??
                cfg.requiredRunTimeMs ??
                60000
            ),


        // Availability may legitimately exceed
        // 100% under this planned-downtime model.
        availabilityMayExceed100:
            true,


        source:
            "shift-summary",

        updatedAt:
            new Date().toISOString()
    }
};


// ========================================================
// SAVE TO MONGODB
// ========================================================

msg.collection =
    "shifts";

msg.operation =
    "insertOne";


return msg;

const result = msg.payload || {};

if (!result.lineStats || !msg.shiftDocumentId) {
    msg.statusCode = 500;
    msg.req = msg._httpReq || msg.req;
    msg.res = msg._httpRes || msg.res;
    msg.payload = {
        success: false,
        error: "Shift summary recalculation failed"
    };
    return [null, msg];
}

const newStats = result.lineStats;
newStats.updatedAt = new Date().toISOString();

msg.recalculatedLineStats = newStats;

msg.collection = "shifts";
msg.operation = "updateOne";
msg.payload = [
    { _id: msg.shiftDocumentId },
    {
        $set: {
            lineStats: newStats,
            updatedAt: new Date().toISOString()
        }
    }
];

return [msg, null];

const s = msg.recalculatedLineStats || {};

msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json" };
msg.req = msg._httpReq || msg.req;
msg.res = msg._httpRes || msg.res;

msg.payload = {
    success: true,
    message: "Downtime updated and shift summary recalculated successfully",
    shiftSummaryUpdated: true,
    line: s.lineName,
    date: s.shiftDate,
    shift: s.shift,
    production: s.production,
    tileCount: s.tileCount,
    totalDowntimeMinutes: s.totalDowntimeMinutes,
    plannedDowntimeMinutes: s.plannedDowntimeMinutes,
    unplannedDowntimeMinutes: s.unplannedDowntimeMinutes,
    actualOperatingMinutes: s.actualOperatingMinutes,
    availability: s.availability,
    performance: s.performance,
    quality: s.quality,
    ole: s.ole
};

return msg;

const headers = msg.req?.headers || {};

return {
    payload: {
        endpoint: msg.req?.url,
        username: headers["x-ruhanex-user"] || null,
        role: headers["x-ruhanex-role"] || null
    }
};

return (function prepareDowntimeAudit(msg) {
  const fail=(status,error)=>{msg.statusCode=status;msg.payload={success:false,error};return [null,msg];};
  const headers=msg.req?.headers||{};
  const username=headers['x-ruhanex-user'],role=headers['x-ruhanex-role'];
  if(typeof username!=='string'||!username.trim()||username.length>100||!['Admin','Manager','Line Supervisor','JE'].includes(role))return fail(401,'Authenticated user identity is required for this change.');
  const args=msg.payload;
